// The PIAX range: one source for every section that shows pads, packs or prices.
// Values live in productCatalog.json (from the Final Revised product report); this module adds the box photos
// and helpers. Box photos are generated by scripts/generate-pack-images.py from the same catalogue.
import catalog from './productCatalog.json'

const boxPhotos = import.meta.glob('../assets/products/piax-*.webp', { eager: true, import: 'default' })
const boxPhoto = (padId, format) => boxPhotos[`../assets/products/piax-${padId}-${format.id}-${format.count}.webp`]

export const colours = catalog.colours

// Trial (4), Standard (10) and Value (30): every pad is sold in all three.
export const packFormats = catalog.packFormats

// Pads, in size order. Each pack: `mrp` is the printed MRP (top of the report's range) and `price` what the website
// charges (bottom of the range). The difference is the discount shown on product cards (see productCatalog.json).
export const pads = catalog.pads.map(({ mrp, mrpRange, ...pad }) => ({
  ...pad,
  packs: packFormats.map((format) => ({
    id: `piax-${pad.id}-${format.id}-${format.count}`,
    format: format.id,
    formatName: format.name,
    label: `${pad.name.replace('PIAX ', '')} ${format.count}`,
    count: format.count,
    mrp: mrpRange[format.id][1],
    price: mrp[format.id],
    mrpRange: mrpRange[format.id],
    image: boxPhoto(pad.id, format),
  })),
}))

// Mixed-size packs are post-launch formats in the product report, so none are sold yet.
export const bundles = []

// Product features with their validation status (validated | prohibited).
export const productFeatures = catalog.features

// Features cleared for the shop listing, shared by every pad.
export const sharedFeatures = productFeatures
  .filter((feature) => feature.status === 'validated' && feature.approvedFor.includes('product_listing') && feature.id !== 'length' && feature.id !== 'regular-pad')
  .map((feature) => feature.label)

export const directionsOfUse = catalog.directionsOfUse

export const padById = Object.fromEntries(pads.map((pad) => [pad.id, pad]))

// The pack a pad is usually bought in.
export const standardPack = (pad) => pad.packs.find((pack) => pack.format === 'standard') ?? pad.packs[0]

export const discount = ({ mrp, price }) => (mrp > price ? Math.round((1 - price / mrp) * 100) : 0)
export const perPad = ({ price, count }) => (price / count).toFixed(2).replace(/\.00$/, '')
